const cuIO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){cuIO.unobserve(e.target);countUp(e.target)}}),{threshold:.4});
const countUp=el=>{if(reduce||el.dataset.y!==undefined||el._cu)return;el._cu=1;const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const nodes=[];while(w.nextNode())nodes.push(w.currentNode);
 const items=nodes.map(n=>({n,o:n.textContent}));const re=/\d+(?:[.,'  ]\d+)*/g;
 const t0=performance.now(),D=900;
 const fmt=(m,p)=>{if(/^(18|19|20)\d\d$/.test(m))return m;let dec="",dp=0;const mm=m.match(/[.,](\d{1,2})$/);
   if(mm&&!(m.includes(",")&&lang==="en"&&mm[1].length===3)){dec=m[m.length-mm[1].length-1];dp=mm[1].length}
   const clean=dp?m.slice(0,-(dp+1)).replace(/\D/g,"")+"."+mm[1]:m.replace(/\D/g,"");const v=parseFloat(clean)*p;
   let s=v.toFixed(dp);if(dec)s=s.replace(".",dec);const ip=s.split(dec||".")[0];if(ip.length>3&&/\d[,'  ]\d{3}/.test(m)){const sep=m.match(/\d([,'  ])\d{3}/)[1];s=s.replace(/^\d+/,x=>x.replace(/\B(?=(\d{3})+$)/g,sep))}return s};
 const step=now=>{const p=Math.min(1,(now-t0)/D),e=1-Math.pow(1-p,3);items.forEach(it=>it.n.textContent=it.o.replace(re,m=>fmt(m,e)));if(p<1)requestAnimationFrame(step);else el._cu=0};requestAnimationFrame(step)};
