/* ---------- line chart with tooltip ---------- */
const chart=(fig,series,o={})=>{const s=fig.querySelector("svg");
 let tip=fig.querySelector(".tip");if(!tip){tip=document.createElement("div");tip.className="tip";fig.appendChild(tip)}
 const draw=()=>{const W=s.clientWidth,H=s.clientHeight;if(!W)return;const n=W<520;
  const all=series.flatMap(x=>x.pts);const x0=o.x0??Math.min(...all.map(p=>p[0])),x1=o.x1??Math.max(...all.map(p=>p[0]));
  const yMax=o.yMax??Math.ceil(Math.max(...all.map(p=>p[1]))*1.15/10)*10,yMin=o.yMin??0;
  const Lm=n?34:46,R=n?14:o.r??70,T=20,B=34,X=v=>Lm+(W-Lm-R)*(v-x0)/(x1-x0),Y=v=>T+(H-T-B)*(1-(v-yMin)/(yMax-yMin));
  let g="";const ticks=o.ticks||5;
  for(let i=0;i<=ticks;i++){const v=yMin+(yMax-yMin)*i/ticks;g+=`<line x1="${Lm}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" stroke="${css('--line')}"/><text x="${Lm-8}" y="${Y(v)+4}" text-anchor="end" font-size="12" fill="${css('--mute')}">${Math.round(v)}${n&&o.unit===" kg"?"":o.unit||""}</text>`}
  let xt=o.xt;if(!xt){const st=[1,2,5,10,20].find(q=>(x1-x0)/q<=6);xt=[x0];for(let v=Math.ceil(x0/st)*st;v<x1;v+=st)if(v-x0>=st*.6&&x1-v>=st*.6)xt.push(v);xt.push(x1)}
  (n?[xt[0],xt[xt.length-1]]:xt).forEach(v=>g+=`<text x="${X(v)}" y="${H-10}" text-anchor="middle" font-size="12" fill="${css('--mute')}">${v}</text>`);
  (o.marks||[]).forEach(m=>{g+=`<line x1="${X(m.x)}" x2="${X(m.x)}" y1="${T}" y2="${H-B}" stroke="${css('--ink')}" stroke-dasharray="2 3"/><text x="${X(m.x)+6}" y="${T+12}" font-size="12" fill="${css('--ink')}">${m.t}</text>`});
  const P=[];
  series.forEach(se=>{const col=css(se.c);let solid="",dash="";
   for(let i=1;i<se.pts.length;i++){const a=se.pts[i-1],b=se.pts[i];const seg=`M${X(a[0])},${Y(a[1])}L${X(b[0])},${Y(b[1])}`;(a[2]||b[2])?dash+=seg:solid+=seg}
   g+=`<path d="${solid}" fill="none" stroke="${col}" stroke-width="2.5" stroke-linecap="round"/><path d="${dash}" fill="none" stroke="${col}" stroke-width="2.5" stroke-dasharray="4 4"/>`;
   if(o.dots)se.pts.forEach(p=>g+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="3.5" fill="${css('--bg')}" stroke="${col}" stroke-width="2"/>`);
   const lp=se.pts[se.pts.length-1];if(!n&&se.label)g+=`<text x="${X(lp[0])+8}" y="${Y(lp[1])+4}" font-size="13" font-weight="600" fill="${col}">${se.label}</text>`;
   se.pts.forEach(p=>P.push({x:X(p[0]),y:Y(p[1]),yr:p[0],v:p[1],e:p[2],lab:se.label||se[lang]||"",src:se.src||o.src||"",col}));});
  g+=`<line id="hlx" y1="${T}" y2="${H-B}" stroke="${css('--ink')}" stroke-opacity=".25" stroke-dasharray="3 3" opacity="0"/><circle id="hl" r="6" fill="#fff" stroke-width="3" opacity="0"/>`;
  s.innerHTML=g;fig._P=P;fig._unit=o.unit===" kg"?" kg":o.unit||"";};
 if(!fig._tipBound){fig._tipBound=1;
  const move=ev=>{const P=fig._P;if(!P||!P.length)return;const r=s.getBoundingClientRect(),mx=ev.clientX-r.left,my=ev.clientY-r.top;
   let best=null,bd=1e9;P.forEach(p=>{const d=Math.abs(p.x-mx)*2+Math.abs(p.y-my)*.5;if(d<bd){bd=d;best=p}});
   if(!best||Math.abs(best.x-mx)>60){tip.style.opacity=0;return}
   const hl=s.querySelector("#hl");if(hl){hl.setAttribute("cx",best.x);hl.setAttribute("cy",best.y);hl.setAttribute("stroke",best.col);hl.setAttribute("opacity",1)}
   const hx=s.querySelector("#hlx");if(hx){hx.setAttribute("x1",best.x);hx.setAttribute("x2",best.x);hx.setAttribute("opacity",1)}
   const same=P.filter(p=>p.yr===best.yr&&p!==best);
   tip.innerHTML=`<div class="th"><i style="background:${best.col}"></i>${best.lab||""}<span class="ty">${best.yr}</span></div><div class="tv">${nf(best.v)}<span>${fig._unit}</span></div>${same.map(p=>`<div class="to"><i style="background:${p.col}"></i>${p.lab}: <b>${nf(p.v)}${fig._unit}</b></div>`).join("")}<small>${best.e?tx("Estimate · ","Estimation · "):""}${tx("Source","Source")}: ${best.src}</small>`;tip.classList.add("rich");
   tip.style.left=Math.max(80,Math.min(r.width-80,best.x))+"px";tip.style.top=best.y+"px";tip.style.opacity=1};
  s.addEventListener("pointermove",move);s.addEventListener("pointerdown",move);
  s.addEventListener("pointerleave",()=>{tip.style.opacity=0;{const hx=s.querySelector("#hlx");if(hx)hx.setAttribute("opacity",0);const hl=s.querySelector("#hl");if(hl)hl.setAttribute("opacity",0)};const hl=s.querySelector("#hl");hl&&hl.setAttribute("opacity",0)})}
 fig._draw=draw;draw();};
const figs=[];const reg=f=>{figs.push(f);new ResizeObserver(()=>f._render&&f._render()).observe(f)};
const redrawAll=()=>{figs.forEach(f=>f._render&&f._render());drawMap()};
matchMedia("(prefers-color-scheme: dark)").addEventListener("change",redrawAll);
new MutationObserver(redrawAll).observe(document.documentElement,{attributes:true,attributeFilter:["data-theme"]});

