 let g=`<path d="${poly(border)}" fill="${css('--soft')}" stroke="${css('--ink')}" stroke-width="2" stroke-linejoin="round"/>`;
 lakes.forEach(l=>g+=`<path d="${poly(l)}" fill="${css('--blue')}" opacity=".25"/>`);
 g+=`<path d="${rosti.map((p,i)=>(i?"L":"M")+PX(...p).join(",")).join("")}" fill="none" stroke="${css('--mute')}" stroke-width="2" stroke-dasharray="6 6"/>`;
