 const [ax,ay]=PX(...cur.at);const right=ax<=650;cities.forEach(c=>{const [x,y]=PX(c[1],c[2]);if(Math.hypot(x-ax,y-ay)<60)return;if(Math.abs(y-ay)<75&&(right?x>ax-30&&x<ax+460:x<ax+30&&x>ax-460))return;g+=`<circle cx="${x}" cy="${y}" r="4" fill="${css('--mute')}"/><text x="${x+8}" y="${y-8}" font-size="22" fill="${css('--mute')}">${c[0]}</text>`});
