 g+=`<g class="pin"><circle cx="${x}" cy="${y}" r="30" fill="${css('--red')}" opacity=".15"/><circle cx="${x}" cy="${y}" r="16" fill="${css('--red')}"/></g>`;
 const lx=x>650?x-26:x+26,anc=x>650?"end":"start";
 const halo=`paint-order="stroke" stroke="${css('--bg')}" stroke-width="8" stroke-linejoin="round"`;g+=`<text x="${lx}" y="${y-22}" text-anchor="${anc}" font-size="34" font-weight="600" fill="${css('--ink')}" ${halo}>${cur.y} · ${cur.pl}</text><text x="${lx}" y="${y+14}" text-anchor="${anc}" font-size="26" fill="${css('--red')}" ${halo}>${cur.dish}</text>`;
