const stopPlay=()=>{clearInterval(playT);playT=null;document.getElementById("rPlay").textContent=tx("Play","Lecture")};
document.getElementById("rPlay").onclick=()=>{if(playT)return stopPlay();document.getElementById("rPlay").textContent=tx("Pause","Pause");go(si+1);playT=setInterval(()=>{if(si===11)return stopPlay();go(si+1)},2600)};
