/* ---------- guess ---------- */
const gFig=document.getElementById("gFig"),gs=gFig.querySelector("svg");const gYears=[2018,2019,2020,2021,2022,2023,2024];
const actual={2017:56.1,2018:55.5,2019:53.7,2021:51.3,2022:46.9,2023:45.5,2024:45.5};
let guess={},revealed=false;
const gGeo=()=>{const W=gs.clientWidth,H=gs.clientHeight,Lm=46,R=24,T=20,B=34;return{W,H,X:v=>Lm+(W-Lm-R)*(v-2017)/7,Y:v=>T+(H-T-B)*(1-(v-30)/40),iY:y=>30+40*(1-(y-T)/(H-T-B)),iX:x=>2017+7*(x-Lm)/(W-Lm-R),Lm,R}};
const gDraw=()=>{const G=gGeo();if(!G.W)return;let g="";
 for(let v=30;v<=70;v+=10)g+=`<line x1="${G.Lm}" x2="${G.W-G.R}" y1="${G.Y(v)}" y2="${G.Y(v)}" stroke="${css('--line')}"/><text x="${G.Lm-8}" y="${G.Y(v)+4}" text-anchor="end" font-size="12" fill="${css('--mute')}">${v}</text>`;
 [2017,...gYears].forEach(y=>g+=`<text x="${G.X(y)}" y="${G.H-10}" text-anchor="middle" font-size="12" fill="${css('--mute')}">${G.W<520&&y%2?"":y}</text>`);
 if(!Object.keys(guess).length)g+=`<rect x="${G.X(2017.4)}" y="${G.Y(70)}" width="${G.X(2024)-G.X(2017.4)}" height="${G.Y(30)-G.Y(70)}" fill="${css('--ink')}" opacity=".04"/><text x="${(G.X(2017.4)+G.X(2024))/2}" y="${G.Y(50)}" text-anchor="middle" font-size="16" fill="${css('--mute')}">${tx("Draw here →","Dessinez ici →")}</text>`;
 const gp=[[2017,56.1],...gYears.filter(y=>guess[y]!=null).map(y=>[y,guess[y]])];
 g+=`<path d="${gp.map((p,i)=>(i?"L":"M")+G.X(p[0])+","+G.Y(p[1])).join("")}" fill="none" stroke="${css('--ink')}" stroke-width="2.5" stroke-dasharray="5 4"/>`;
 gp.slice(1).forEach(p=>g+=`<circle cx="${G.X(p[0])}" cy="${G.Y(p[1])}" r="4" fill="${css('--ink')}"/>`);
 if(revealed){const ap=Object.entries(actual).map(([y,v])=>[+y,v]);g+=`<path d="${ap.map((p,i)=>(i?"L":"M")+G.X(p[0])+","+G.Y(p[1])).join("")}" fill="none" stroke="${css('--blue')}" stroke-width="3"/>`;
  ap.forEach(p=>g+=`<circle cx="${G.X(p[0])}" cy="${G.Y(p[1])}" r="4.5" fill="${css('--bg')}" stroke="${css('--blue')}" stroke-width="2.5"/>`)}
 g+=`<circle cx="${G.X(2017)}" cy="${G.Y(56.1)}" r="6" fill="${css('--blue')}"/><text x="${G.X(2017)+10}" y="${G.Y(56.1)-10}" font-size="13" fill="${css('--blue')}">56.1 kg</text>`;
 gs.innerHTML=g;document.getElementById("gShow").disabled=guess[2024]==null||revealed;};
let drawing=false;
const gSet=ev=>{if(revealed)return;const G=gGeo(),r=gs.getBoundingClientRect();const yr=Math.round(G.iX(ev.clientX-r.left));if(yr<2018||yr>2024)return;
 const v=Math.max(30,Math.min(70,G.iY(ev.clientY-r.top)));guess[yr]=Math.round(v*10)/10;
 gYears.forEach(y=>{if(guess[y]==null&&y<yr){const prev=[2017,...gYears].filter(q=>q<y&&(q===2017||guess[q]!=null)).pop();guess[y]=prev===2017?56.1:guess[prev]}});gDraw()};
gs.addEventListener("pointerdown",e=>{drawing=true;gs.setPointerCapture(e.pointerId);gSet(e)});
gs.addEventListener("pointermove",e=>drawing&&gSet(e));gs.addEventListener("pointerup",()=>drawing=false);
gFig._render=gDraw;reg(gFig);
document.getElementById("gShow").onclick=()=>{revealed=true;gDraw();const d=guess[2024]-45.5;const res=document.getElementById("gRes");res.style.display="";
 document.getElementById("gNum").textContent=`45.5 kg`;
 document.getElementById("gTxt").textContent=tx(`Real value in 2024. You guessed ${nf(guess[2024])} kg, ${Math.abs(d)<2?"very close!":d>0?nf(d)+" kg too high. Milk fell faster than most people expect.":nf(-d)+" kg too low."}`,`Valeur réelle en 2024. Votre estimation : ${nf(guess[2024])} kg, ${Math.abs(d)<2?"tout près !":d>0?nf(d)+" kg de trop. Le lait a baissé plus vite qu'on ne le pense.":nf(-d)+" kg de moins."}`);countUp(document.getElementById("gNum"))};
document.getElementById("gReset").onclick=()=>{guess={};revealed=false;document.getElementById("gRes").style.display="none";gDraw()};

