/* build a week */
const menuD=()=>[["fondue",tx("Fondue","Fondue"),0,200],["raclette",tx("Raclette","Raclette"),50,200],["rosti",tx("Rösti with cheese and egg","Rösti au fromage et œuf"),0,40],["magronen",tx("Älplermagronen","Älplermagronen"),0,80],["cervelat",tx("Cervelat and potato salad","Cervelas et salade de pommes de terre"),100,0],["gesch",tx("Geschnetzeltes and rösti","Émincé zurichois et rösti"),150,0],["chicken",tx("Chicken and rice","Poulet et riz"),150,0],["pizza",tx("Pizza Margherita","Pizza Margherita"),0,120],["burger",tx("Veggie burger","Burger végétal"),0,30],["muesli",tx("Birchermüesli","Birchermüesli"),0,0]];
