const days=()=>tx(["Mon","Tue","Wed","Thu","Fri","Sat","Sun"],["Lun","Mar","Mer","Jeu","Ven","Sam","Dim"]);
const week=()=>{const M=menuD(),get=k=>M.find(m=>m[0]===k);
 document.getElementById("menu").innerHTML=M.map(m=>`<button class="chip" data-m="${m[0]}">${m[1]} <span class="mute" style="font-size:12px">${m[2]?m[2]+" g "+tx("meat","viande"):""}${m[2]&&m[3]?" · ":""}${m[3]?m[3]+" g "+tx("cheese","fromage"):""}${!m[2]&&!m[3]?tx("no meat, no cheese","ni viande ni fromage"):""}</span></button>`).join("");
 document.getElementById("weekDays").innerHTML=days().map((d,i)=>`<button class="day${wk[i]?" full":""}" data-d="${i}"><b>${d}</b>${wk[i]?get(wk[i])[1]:"+"}</button>`).join("");
 const meat=wk.reduce((s,k)=>s+(k?get(k)[2]:0),0),ch=wk.reduce((s,k)=>s+(k?get(k)[3]:0),0);
 let t,p;
 if(!wk.some(Boolean)){t=tx("Empty week","Semaine vide");p=tx("Add dishes to start.","Ajoutez des plats pour commencer.")}
 else if(meat===0){t=tx("Vegetarian week","Semaine végétarienne");p=tx("Like 5.3% of people in Switzerland (2024).","Comme 5,3 % de la population suisse (2024).")}
 else if(meat<=300){t=tx("Flexitarian week","Semaine flexitarienne");p=tx("Within the 300 g limit, like about 1 in 4 Swiss households in 2024.","Sous la limite de 300 g, comme environ 1 ménage suisse sur 4 en 2024.")}
 else if(meat<=700){t=tx("Average Swiss week","Semaine suisse moyenne");p=tx(`Close to the ~700 g people actually eat. ${meat-300} g above the flexitarian limit.`,`Proche des ~700 g réellement mangés. ${meat-300} g au-dessus de la limite flexitarienne.`)}
 else{t=tx("Meat-heavy week","Semaine très carnée");p=tx(`More than the Swiss average. ${meat-300} g above the flexitarian limit.`,`Plus que la moyenne suisse. ${meat-300} g au-dessus de la limite flexitarienne.`)}
 if(ch>455)p+=tx(` And ${ch} g of cheese: more than the Swiss average of about 455 g a week.`,` Et ${ch} g de fromage : plus que la moyenne suisse d'environ 455 g par semaine.`);
 document.getElementById("pTitle").textContent=t;document.getElementById("pText").textContent=p;
 const mt=(lab,v,g,a,max,c)=>{const pc=x=>Math.min(x/max*100,100);return `<div class="meter"><div class="k"><b>${lab}: ${v} g</b><span class="mute">${tx("Swiss avg","Moy. suisse")} ${a} g${g?` · ${tx("limit","limite")} ${g} g`:""}</span></div><div class="bar"><i style="width:${pc(v)}%;background:var(${g&&v>g?"--red":c})"></i>${g?`<s style="left:${pc(g)}%"></s>`:""}<u style="left:${pc(a)}%"></u></div></div>`};
 document.getElementById("meters").innerHTML=mt(tx("Meat","Viande"),meat,300,700,1100,"--green")+mt(tx("Cheese","Fromage"),ch,null,455,1100,"--gold");
 document.querySelectorAll("#menu .chip").forEach(c=>c.onclick=()=>{const i=wk.findIndex(x=>!x);if(i<0)wk[6]=c.dataset.m;else wk[i]=c.dataset.m;week()});
 document.querySelectorAll("#weekDays .day").forEach(d=>d.onclick=()=>{wk[+d.dataset.d]=null;week()});};
document.querySelectorAll("[data-p]").forEach(b=>b.onclick=()=>{wk=[...presets[b.dataset.p]];week()});

