let qi=0,score=0,answered=false;
const quiz=()=>{const Qs=Q(),q=Qs[qi];answered=false;document.getElementById("qQ").textContent=`${qi+1}/${Qs.length} · ${q[0]}`;
 document.getElementById("qE").innerHTML="";document.getElementById("qScore").textContent=tx(`Score: ${score} / ${Qs.length}`,`Score : ${score} / ${Qs.length}`);
 document.getElementById("qA").innerHTML=q[1].map((a,i)=>`<button data-i="${i}">${a}</button>`).join("");
 document.querySelectorAll("#qA button").forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const ok=+b.dataset.i===q[2];if(ok)score++;
  b.classList.add(ok?"ok":"no");document.querySelectorAll("#qA button")[q[2]].classList.add("ok");
  const mx=Math.max(...q[3].map(r=>r[1]));const E=document.getElementById("qE");
  E.innerHTML=`<p class="small"><b>${ok?tx("Correct!","Bravo !"):tx("Not quite.","Pas tout à fait.")}</b> ${tx("Here is the data:","Voici les données :")}</p><div class="rows">${q[3].map(r=>`<div class="row"><div class="lab"><span>${r[0]}</span><span>${nf(r[1],r[1]*10%1?2:1)}${q[4]}</span></div><div class="track"><i data-w="${r[1]/mx*100}%" style="background:var(${r[2]})"></i></div></div>`).join("")}</div>`;
  bars(E);document.getElementById("qScore").textContent=tx(`Score: ${score} / ${Qs.length}`,`Score : ${score} / ${Qs.length}`)});};
document.getElementById("qNext").onclick=()=>{qi=(qi+1)%Q().length;if(qi===0)score=0;quiz()};

