const hilo=()=>{const L_=HL(),el=document.getElementById("hilo");
 if(hlI>=L_.length){el.innerHTML=`<h3>${tx("Higher or lower?","Plus haut ou plus bas ?")}</h3><div class="bigstat" style="margin:18px 0 6px">${hlS} / ${L_.length}</div><p>${hlS>=7?tx("Data expert!","Expert des données !"):hlS>=5?tx("Well done. Some trends are surprising.","Bien joué. Certaines tendances surprennent."):tx("The Swiss plate changes in unexpected ways.","L'assiette suisse change de façon inattendue.")}</p><button class="btn" id="hlR">${tx("Play again","Rejouer")}</button>`;
  document.getElementById("hlR").onclick=()=>{hlI=0;hlS=0;hlA=null;hilo()};return}
 const q=L_[hlI],fmt=v=>q[5]==="CHF mio"?`CHF ${nf(v,0)} mio`:`${nf(v)} ${q[5]}`;
 const res=hlA===null?"":(()=>{const up=q[4]>q[2],ok=hlA===up,mx=Math.max(q[2],q[4]);return `<p style="margin:12px 0 6px"><b style="color:var(${ok?"--green":"--red"})">${ok?tx("Right!","Exact !"):tx("Not this time.","Pas cette fois.")}</b> ${up?tx("Higher","Plus haut"):tx("Lower","Plus bas")}: ${fmt(q[4])}</p>
  <div class="rows"><div class="row"><div class="lab"><span>${q[1]}</span><span>${fmt(q[2])}</span></div><div class="track"><i style="width:${q[2]/mx*100}%;background:var(--rule)"></i></div></div><div class="row"><div class="lab"><span>${q[3]}</span><span>${fmt(q[4])}</span></div><div class="track"><i style="width:${q[4]/mx*100}%;background:var(${ok?"--green":"--red"})"></i></div></div></div>
  <button class="btn" id="hlN" style="margin-top:14px">${hlI===L_.length-1?tx("See my score","Voir mon score"):tx("Next","Suivant")}</button>`})();
 el.innerHTML=`<div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline"><h3>${tx("Higher or lower?","Plus haut ou plus bas ?")}</h3><span class="small mute">${hlI+1}/${L_.length} · ${tx("score","score")} ${hlS}</span></div>
 <p class="small mute" style="margin:0">${tx("Each number changed. Guess the direction.","Chaque chiffre a changé. Devinez dans quel sens.")}</p>
 <div class="small" style="margin-top:14px">${q[0]}</div><div class="bigstat" style="margin:4px 0">${fmt(q[2])}</div><div class="small mute">${tx(`in ${q[1]}. And in ${q[3]}?`,`en ${q[1]}. Et en ${q[3]} ?`)}</div>
 ${hlA===null?`<div class="ctrl"><button class="btn ghost" data-a="1">▲ ${tx("Higher","Plus haut")}</button><button class="btn ghost" data-a="0">▼ ${tx("Lower","Plus bas")}</button></div>`:res}`;
 el.querySelectorAll("[data-a]").forEach(b=>b.onclick=()=>{hlA=b.dataset.a==="1";if(hlA===(q[4]>q[2]))hlS++;hilo()});
 const nx=document.getElementById("hlN");if(nx)nx.onclick=()=>{hlI++;hlA=null;hilo()};};
