 japan:[{id:"j1",ll:[139.7,35.7],lab:"Tokyo",off:[12,4,"start"],col:"--blue",card:`<h3>${tx("Japan: fish to meat","Japon : du poisson à la viande")}</h3><p>${tx("Pork per person rose from 1.1 kg (1960) to 11.7 kg (2008). In 2006 meat overtook fish for the first time.","Le porc par personne est passé de 1,1 kg (1960) à 11,7 kg (2008). En 2006, la viande a dépassé le poisson pour la première fois.")}</p>${miniTT("JPN")}`}],
