let myI=0,myS=0,myA=null,myLog=[];
const myth=()=>{const L_=MY(),el=document.getElementById("myCard");if(!el)return;
 document.getElementById("myDots").innerHTML=L_.map((_,i)=>`<i class="${myLog[i]===1?"ok":myLog[i]===0?"no":i===myI?"cur":""}"></i>`).join("");
 document.getElementById("myScore").textContent=`${myS} / ${L_.length}`;
 if(myI>=L_.length){el.innerHTML=`<h3 style="font-size:26px">${myS>=10?tx("Food data expert!","Expert des données alimentaires !"):myS>=7?tx("Well done!","Bien joué !"):tx("Lots of surprises, right?","Beaucoup de surprises, non ?")}</h3><p>${tx(`You got ${myS} of ${L_.length}.`,`Vous avez ${myS} sur ${L_.length}.`)}</p><div class="ctrl"><button class="btn" id="myR">${tx("Play again","Rejouer")}</button><a class="btn ghost" href="#summary" style="display:inline-flex;align-items:center;text-decoration:none">${tx("See my summary card","Voir ma carte résumé")}</a></div>`;document.getElementById("myR").onclick=()=>{myI=0;myS=0;myA=null;myLog=[];myth()};return}
 const q=L_[myI],mx=Math.max(...q[3].map(r=>r[1]));
 el.innerHTML=`<div class="small mute">${myI+1} / ${L_.length}</div><h3 class="mq">“${q[0]}”</h3>`+(myA===null?`<div class="ctrl"><button class="btn mbtn" data-my="0">${tx("Myth","Mythe")}</button><button class="btn mbtn fact" data-my="1">${tx("Fact","Fait")}</button><button class="btn ghost sm" id="wxBk">${tx("Back to the map","Retour à la carte")}</button></div>`:
 `<div class="verd ${myA===q[1]?"ok":"no"}">${myA===q[1]?tx("Right!","Exact !"):tx("Not quite.","Pas tout à fait.")} ${tx("It's a","C'est un")} <b>${q[1]?tx("fact","fait"):tx("myth","mythe")}</b>.</div><p>${q[2]}</p><div class="rows">${q[3].map((r,i)=>`<div class="row"><div class="lab"><span>${r[0]}</span><span>${nf(r[1],r[1]%1?1:0)}${q[4]}</span></div><div class="track"><i style="width:${r[1]/mx*100}%;background:var(${i?"--rule":"--red"})"></i></div></div>`).join("")}</div><button class="btn" id="myN" style="margin-top:14px">${myI===L_.length-1?tx("See my score","Voir mon score"):tx("Next","Suivant")}</button>`);
 el.querySelectorAll("[data-my]").forEach(b=>b.onclick=()=>{myA=+b.dataset.my;const ok=myA===q[1];if(ok)myS++;myLog[myI]=ok?1:0;myth()});
 const n=document.getElementById("myN");if(n)n.onclick=()=>{myI++;myA=null;myth()}};

